                if blk.get('statementPaymentStatus')=='HAS_DEBT' and blk.get('remainingDebt',0)<=0: flags.append(f"{cn} {k} HAS_DEBT but remainingDebt<=0")
        if dd.get('lastPayDate') and dd['lastPayDate']<'12.10.2026' and dd['lastPayDate'][3:5]=='10': flags.append(f"{cn} lpd passed? {dd['lastPayDate']} sd={dd.get('statementDate')}")
        if dd.get('lastPayDate')=='12.10.2026': flags.append(f"{cn} due today")
        if dd.get('statementDate')=='12.10.2026' or dd.get('nextStatementDate')=='12.10.2026': flags.append(f"{cn} statement today sd={dd.get('statementDate')} nsd={dd.get('nextStatementDate')}")
    if em.get('http')!=200: flags.append(f"email http={em.get('http')}")
    if pdf is None: flags.append("no pdf.send entry")
    elif pdf.get('http')!=200: flags.append(f"pdf http={pdf.get('http')}")
    wk=s.get('statement.week.get',{})
    for cn,w in wk.items():
        if w['http']!=200: flags.append(f"{cn} week.get http={w['http']}")
        elif w['response']['data'].get('relationType'): flags.append(f"{cn} rel={w['response']['data']['relationType']} related={w['response']['data'].get('relatedCardProductName')}")
    ch=s.get('statement.week.change',{})
    for cn,w in ch.items():
        for wk_,r in w.items():
            if r['http']!=200: flags.append(f"{cn} change wk{wk_} http={r['http']}")
    dec=s.get('statement.week.decide',{})
    for cn,w in dec.items():
        for wk_,r in w.items():
            if r['http']!=200: flags.append(f"{cn} decide wk{wk_} http={r['http']}")
    if cl.get('http')!=200: flags.append(f"cards.list http={cl.get('http')}")
    print(c['customerNo'], c['firstName'], '|', '; '.join(flags))
