    nodes["fetch_balance"] = api_node("fetch_balance", "cards.balance", {"cardNumber": "{{card_number}}"}, "compose_reading", [],
                                      mapping=[{"path": "data", "variable": "balance_body"}, {"path": "data.data", "variable": "balance_data"}])
    nodes["compose_reading"] = code_node("compose_reading", CODE_COMPOSE, "read_debt", [
        t("end_agent_service", "balance failed", cond_eq("reading_state", "error")),
        t("end_nodebt", "no debt, single card: read and go to menu", cond_eq("reading_state", "nodebt_end")),
    ])
    nodes["read_debt"] = {
        "name": "read_debt", "node_type": "conversation", "on_enter": {"type": "tts", "text": "{{reading_text}}"},
        "task_message": READ_PROMPT, "max_node_turns": 14, "max_turn_transition": "end_menu",
