"""Builder for the Freya Bank statement-debt phone agent (final case)."""
import json, sys, os, pathlib
ROOT = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT))
import freya

MOCK = os.environ.get("FREYA_MOCK_URL", "https://freya-bank-mock-fable.freya-faruk.workers.dev")
BASE = MOCK + "/voice/v1/"

# ---------------------------------------------------------------- shared python prelude for code nodes
PRELUDE = r'''
import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
def _three(n):
    h = n // 100; t = (n % 100) // 10; o = n % 10; parts = []
    if h: parts.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t: parts.append(TENS[t])
    if o: parts.append(ONES[o])
    return ' '.join(parts)
def words(n):
    n = int(n)
    if n == 0: return 'sıfır'
    out = []
    for div, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        g = n // div; n = n % div
        if g:
            out.append(name if (g == 1 and name == 'bin') else _three(g) + ' ' + name)
    if n: out.append(_three(n))
    return ' '.join(out)
def amt(v, cur):
    try: v = float(v)
    except Exception: v = 0.0
    if v < 0: v = 0.0
    whole = int(round(v * 100)) // 100; frac = int(round(v * 100)) % 100
    if cur == 'TL':
        return (words(whole) + ' lira ' + words(frac) + ' kuruş') if frac else (words(whole) + ' Türk Lirası')
    unit = 'dolar' if cur == 'USD' else ('Euro' if cur == 'EUR' else 'İngiliz Sterlini')
    sub = 'peni' if cur == 'GBP' else 'sent'
    return words(whole) + ' ' + unit + ((' ' + words(frac) + ' ' + sub) if frac else '')
def dsay(d):
    try:
        dd, mm, yy = str(d).strip().split('.')
        return str(int(dd)) + ' ' + MONTHS[int(mm)] + ' ' + yy
    except Exception:
        return str(d)
def diso(d):
    try:
        dd, mm, yy = str(d).strip().split('.')
        return yy + '-' + mm.zfill(2) + '-' + dd.zfill(2)
    except Exception:
        return ''
def digits_say(s):
    return ' '.join(('sıfır' if ch == '0' else ONES[int(ch)]) for ch in str(s) if ch.isdigit())
def fnum(v):
    try: return float(v)
    except Exception: return 0.0
def today_iso():
    s = str(vars.get('now') or '')[:10]
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s): return s
    return datetime.date.today().isoformat()
def _setpath(root, path, value):
    cur = root
    for i, p in enumerate(path):
        last = i == len(path) - 1
        if isinstance(cur, list):
            idx = int(p)
            while len(cur) <= idx: cur.append(None)
            if last: cur[idx] = value
            else:
                if cur[idx] is None: cur[idx] = [] if path[i + 1].isdigit() else dict()
                cur = cur[idx]
        else:
            if last: cur[p] = value
            else:
                if p not in cur or cur[p] is None: cur[p] = [] if path[i + 1].isdigit() else dict()
                cur = cur[p]
def load(varname, prefix):
    v = vars.get(varname)
    if isinstance(v, str) and v.strip().startswith(('[', '{')):
        try: v = json.loads(v)
        except Exception: pass
    if isinstance(v, (dict, list)) and v: return v
    root = None
    for k in list(vars.keys()):
        if k.startswith(prefix + '.') or k.startswith(prefix + '['):
            rest = k[len(prefix):]
            path = [p for p in re.split(r'[.\[\]]+', rest) if p != '']
            if root is None: root = [] if path and path[0].isdigit() else dict()
            try: _setpath(root, path, vars.get(k))
            except Exception: pass
    return root
def status_of(node):
    for k in (node + '_status_code', node + '_response.status_code'):
        v = vars.get(k)
        if v not in (None, ''):
            try: return int(float(v))
            except Exception: pass
    return 0
'''

CODE_PREP = PRELUDE + r'''
try:
    vars['today_iso'] = today_iso()
    vars['card_pick'] = ''; vars['card_tries'] = 0; vars['pick_feedback'] = ''; vars['next_action'] = ''
    vars['cards_read'] = '[]'
