        for i, c in enumerate(cards):
            if not isinstance(c, dict): continue
            num = str(c.get('cardNumber') or '')
            l4 = str(c.get('cardNumberLast4') or num[-4:])
            name = str(c.get('productName') or '').strip()
            main = str(c.get('isMainCard')).lower() in ('true', '1', 'yes')
            item = dict(n=len(allc) + 1, number=num, last4=l4, name=name, main=main, first6=num[:6])
            allc.append(item)
            if main: elig.append(item)
    if st == 404 or code == 'FB_IVR_CHANNEL_102':
        vars['cards_state'] = 'none'
    elif (st and st != 200) or not allc:
        vars['cards_state'] = 'error' if (st != 200 or not isinstance(cards, list)) else 'none'
    elif not elig:
        vars['cards_state'] = 'none'
    elif len(elig) == 1:
        vars['cards_state'] = 'one'
    else:
        vars['cards_state'] = 'multi'
    vars['cards_json'] = json.dumps(allc, ensure_ascii=False)
    vars['elig_count'] = len(elig)
    lines = []
    for c in allc:
        lines.append(str(c['n']) + ') ' + (c['name'] if c['name'] else '(ürün adı yok)') + ' - son dört hane ' + c['last4'] + ('' if c['main'] else ' (ek kart, borç sorgusuna uygun değil)'))
    vars['card_menu_text'] = '\n'.join(lines)
    names = []
    for c in elig:
        if c['name'] and c['name'] not in names: names.append(c['name'])
    ex = names[:2]
    vars['example_names'] = (' veya '.join(ex)) if ex else ''
    if len(elig) == 1:
        c = elig[0]
        vars['card_number'] = c['number']; vars['card_name'] = c['name']; vars['card_last4'] = c['last4']; vars['card_last4_say'] = digits_say(c['last4'])
    else:
        vars['card_number'] = ''; vars['card_name'] = ''; vars['card_last4'] = ''; vars['card_last4_say'] = ''
    # e-mail
    est = status_of('fetch_email')
    eb = load('email_body', 'fetch_email_response.data')
    email = ''; ctype = ''
    try:
        email = str((eb or dict()).get('data', dict()).get('ibanEmail') or '').strip()
        ctype = str((eb or dict()).get('data', dict()).get('communicationType') or '').strip()
    except Exception: pass
    if est and est != 200:
        vars['email_state'] = 'error'
    elif email and ctype.lower() != 'phone':
        vars['email_state'] = 'yes'
    elif est == 200:
        vars['email_state'] = 'no'
    else:
        vars['email_state'] = 'error'
    vars['email_addr'] = email
    local = email.split('@')[0] if '@' in email else email
    dom = email.split('@')[1] if '@' in email else ''
    if email and (len(local) > 14 or re.search(r'[-_.]{1}.*[-_.]{1}|\d{3,}', local)):
        dname = dom.split('.')[0] if dom else ''
        dname = 'Gmail' if dname.lower() == 'gmail' else dname
        vars['email_say'] = local[:1] + ' ile başlayan ' + dname + ' adresinize'
        vars['email_say_mode'] = 'short'
    else:
        vars['email_say'] = email + ' adresine'
        vars['email_say_mode'] = 'full'
    if vars['email_state'] == 'yes':
        vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    else:
        vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim.'
except Exception as e:
    vars['cards_state'] = 'error'; vars['email_state'] = 'error'; vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim.'
    vars['prep_error'] = str(e)
'''

CODE_RESOLVE = PRELUDE + r'''
def norm(s):
    s = str(s or '').lower()
    s = s.replace('ı', 'i').replace('ş', 's').replace('ğ', 'g').replace('ü', 'u').replace('ö', 'o').replace('ç', 'c').replace('İ', 'i')
    return re.sub(r'[^a-z0-9 ]+', ' ', s).strip()
try:
    pick = str(vars.get('card_pick') or '').strip()
    vars['card_pick'] = ''
    try: allc = json.loads(vars.get('cards_json') or '[]')
    except Exception: allc = []
    elig = [c for c in allc if c.get('main')]
    tries = int(fnum(vars.get('card_tries') or 0))
    state = ''; fb = ''; chosen = None
    p = norm(pick)
    digs = re.sub(r'\D', '', pick)
