# ---------------------------------------------------------------- helpers
def cond_eq(var, val):
    return {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}
def cond_neq(var, val):
    return {"logic": "or", "conditions": [{"variable": var, "operator": "not_equals", "operand": val}]}
def cond_and(*pairs):
    return {"logic": "or", "conditions": [{"logic": "and", "conditions": [{"variable": v, "operator": op, "operand": o} for v, op, o in pairs]}]}
def t(target, desc, cond):
    return {"target_node": target, "description": desc, "condition": cond}
def t_always(target):
    return {"target_node": target, "description": "always", "condition": {"operator": "always"}}
def intent(target, desc):
    return {"target_node": target, "description": desc, "condition": {"operator": "matches_intent", "description": desc}}

def api_node(name, service, body_fields, next_node, transitions, retries=1, mapping=None):
    props = {}
    for k, v in body_fields.items():
        props[k] = {"type": "string", "default": v}
    return {
        "name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": next_node,
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [{
            "type": "function", "config": {"timeoutMs": 40000, "maxRetries": retries},
            "function": {"name": name, "handler": "__function__:api_call", "description": service,
                         "parameters": {"type": "object", "properties": {
                             "url": {"type": "string", "default": BASE + service},
                             "method": {"type": "string", "default": "POST"},
                             "connect_retries": {"type": "number", "default": 2},
                             "headers": {"type": "object", "properties": {
                                 "Content-Type": {"type": "string", "default": "application/json"},
                                 "Accept": {"type": "string", "default": "application/json"},
                                 "Authorization": {"type": "string", "default": "Bearer test-token"}}},
                             "body": {"type": "object", "properties": {
                                 "data": {"type": "object", "properties": props},
                                 "call": {"type": "object", "properties": {"ani": {"type": "string", "default": ""}, "lang": {"type": "string", "default": "tr"}}}
                             }}}}}}],
        "response_mapping": mapping or [],
        "transitions": transitions + [t_always(next_node)],
    }

def code_node(name, code, next_node, transitions):
    return {
        "name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": next_node,
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                         "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": code}, "timeout_ms": {"type": "number", "default": 20000}}}}}],
        "transitions": transitions + [t_always(next_node)],
    }

def end_node(name, fn, text):
    params = {"message_mode": {"type": "string", "default": "custom"}, "spoken_message": {"type": "string", "default": text}} if text else {"message_mode": {"type": "string", "default": "none"}}
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "transitions": [],
            "terminal": {"type": "function", "function": {"name": fn, "handler": "__function__:end_call", "parameters": {"type": "object", "properties": params}}}}

