AFTER_SEND_PROMPT = """Ekstre, kayıtlı e-posta adresine başarıyla gönderildi ve bu arayana söylendi. Tekrar göndermek isterse en fazla üç gönderim yapılabileceğini belirt ve isteği kısa onayla (akış gönderir). Başka adres isterse yalnızca kayıtlı adrese gönderilebildiğini söyle. Teşekkür ederse ya da başka bir şey istemezse kısa veda et; "Sizi ana menüye yönlendiriyorum." cümlesini akış söyler. Bu adımda araç çağrısı yapılmaz."""

NEXT_ACTION_SCHEMA = {
    "name": "next_action", "type": "string",
    "enum_values": ["another_card", "email", "week", "done", "menu_yes", "pay", "agent", "dispute", "third_party", "foreign", "stay"],
    "description": "Arayanın SON mesajındaki isteği: 'another_card' = başka/diğer bir kartının borcunu da öğrenmek istiyor (başka kart sorusuna 'evet' dahil); 'email' = ekstresini e-posta/mail ile istiyor (yalnızca en son ekstre teklifini kabul etmesi dahil); 'week' = hesap kesim tarihini/haftasını/ekstre tarihini değiştirmek istiyor; 'done' = başka bir şey istemiyor, teşekkür ediyor, vedalaşıyor, 'hayır' diyor; 'menu_yes' = ana menüye aktarılmayı kabul ediyor; 'pay' = borcunu ödemek istiyor ya da nasıl/nereden ödeyeceğini soruyor; 'agent' = müşteri temsilcisi/insan/yetkili istiyor; 'dispute' = borcun yanlış olduğunu ya da yaptığı ödemenin görünmediğini söylüyor; 'third_party' = eşinin/annesinin/babasının/başkasının kartı hakkında bilgi ya da işlem istiyor; 'foreign' = Türkçe dışında bir dilde konuşuyor; 'stay' = diğer her şey (tekrar isteği, tek bir bilgi sorusu, konu dışı soru, geçmiş ay ekstresi isteği, şikâyet, rakam/kart numarası isteği).",
    "min_confidence": 0.5,
}
CARD_PICK_SCHEMA = {
    "name": "card_pick", "type": "string",
    "description": "Arayanın seçtiği KART: kart adını (örn. 'Yıldız Premium', 'Yıldız Fly', 'Platinum', 'Miles Gold', 'Pratik') ya da söylediği rakamları SADECE RAKAM olarak yaz (son dört hane '4253'; 'dört iki beş üç' -> '4253'; 'kırk iki elli üç' -> '4253'; son altı veya 16 haneli tam numara da sadece rakam). Tüm kartlarını birden isterse 'all'. Kart seçmediyse boş bırak. Asistanın söylediği kart adlarını değil, yalnızca ARAYANIN seçimini yaz.",
    "min_confidence": 0.4,
}

# ---------------------------------------------------------------- build
def build():
    nodes = {}
    END_AGENT_SERVICE = "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum."
    nodes["fetch_cards"] = api_node("fetch_cards", "cards.list", {"customerNo": "{{customerNumber}}", "aiFlow": "CardOps"}, "fetch_email", [],
                                    mapping=[{"path": "data", "variable": "cards_body"}, {"path": "data.data.cards", "variable": "cards_data"}])
    nodes["fetch_email"] = api_node("fetch_email", "contact.email.get", {"customerNo": "{{customerNumber}}", "intAddressInfoType": "E"}, "prep", [],
                                    mapping=[{"path": "data", "variable": "email_body"}])
    nodes["prep"] = code_node("prep", CODE_PREP, "choose_card", [
        t("end_agent_service", "card list failed", cond_eq("cards_state", "error")),
        t("end_no_card", "no eligible card", cond_eq("cards_state", "none")),
        t("fetch_balance", "single card", cond_eq("cards_state", "one")),
    ])
    nodes["choose_card"] = {
        "name": "choose_card", "node_type": "conversation", "on_enter": {"type": "llm"},
        "task_message": CHOOSE_PROMPT, "max_node_turns": 8, "max_turn_transition": "end_tries",
        "extraction_schema": [CARD_PICK_SCHEMA],
        "transitions": [t("resolve_card", "caller named a card", cond_neq("card_pick", ""))],
    }
    nodes["resolve_card"] = code_node("resolve_card", CODE_RESOLVE, "choose_card", [
        t("fetch_balance", "card resolved", cond_eq("pick_state", "ok")),
        t("end_tries", "three tries used", cond_eq("pick_state", "tries")),
    ])
    nodes["reset_pick"] = code_node("reset_pick", CODE_RESET_PICK, "choose_card", [])
    nodes["fetch_balance"] = api_node("fetch_balance", "cards.balance", {"cardNumber": "{{card_number}}"}, "compose_reading", [],
                                      mapping=[{"path": "data", "variable": "balance_body"}, {"path": "data.data", "variable": "balance_data"}])
    nodes["compose_reading"] = code_node("compose_reading", CODE_COMPOSE, "read_debt", [
        t("end_agent_service", "balance failed", cond_eq("reading_state", "error")),
        t("end_nodebt", "no debt, single card: read and go to menu", cond_eq("reading_state", "nodebt_end")),
    ])
    nodes["read_debt"] = {
        "name": "read_debt", "node_type": "conversation", "on_enter": {"type": "tts", "text": "{{reading_text}}"},
        "task_message": READ_PROMPT, "max_node_turns": 14, "max_turn_transition": "end_menu",
        "extraction_schema": [NEXT_ACTION_SCHEMA, CARD_PICK_SCHEMA],
        "transitions": [
            t("end_agent", "agent wanted", cond_eq("next_action", "agent")),
            t("end_agent_pay", "wants to pay", cond_eq("next_action", "pay")),
            t("end_agent_dispute", "disputes the debt", cond_eq("next_action", "dispute")),
            t("end_third_party", "someone else's card", cond_eq("next_action", "third_party")),
            t("end_menu_aktar", "not Turkish", cond_eq("next_action", "foreign")),
            t("resolve_card", "named another card", cond_and(("card_pick", "not_equals", ""), ("cards_state", "equals", "multi"), ("next_action", "not_equals", "done"))),
            t("reset_pick", "another card", cond_and(("next_action", "equals", "another_card"), ("cards_state", "equals", "multi"))),
            t("email_confirm", "email with registered address", cond_and(("next_action", "equals", "email"), ("email_state", "equals", "yes"))),
            t("email_none", "email but no registered address", cond_and(("next_action", "equals", "email"), ("email_state", "equals", "no"))),
            t("end_agent_service", "email service failed", cond_and(("next_action", "equals", "email"), ("email_state", "equals", "error"))),
            t("fetch_week", "statement week change", cond_eq("next_action", "week")),
            t("end_menu", "nothing else", cond_eq("next_action", "done")),
            t("end_menu", "accepts main menu", cond_eq("next_action", "menu_yes")),
        ],
    }
    # e-mail
    nodes["email_confirm"] = {
        "name": "email_confirm", "node_type": "conversation", "on_enter": {"type": "tts", "text": "Ekstrenizi {{email_say}} göndermemi ister misiniz?"},
        "task_message": EMAIL_PROMPT, "max_node_turns": 6, "max_turn_transition": "end_tries",
        "extraction_schema": [{
            "name": "email_answer", "type": "string", "enum_values": ["yes", "no", "wrong_address", "stay"],
            "description": "Arayanın e-posta gönderim sorusuna cevabı: 'yes' = açık ve net evet/onaylıyorum/gönder; 'no' = hayır/istemiyorum/vazgeçtim; 'wrong_address' = adresin yanlış/eski/artık kendisine ait olmadığını söylüyor; 'stay' = başka adres istiyor, geçmiş ay ekstresi istiyor, belirsiz cevap ('olur herhalde', 'sanırım'), soru soruyor ya da başka bir şey.",
            "min_confidence": 0.5}],
        "transitions": [
            t("send_pdf", "clear yes", cond_eq("email_answer", "yes")),
            t("end_menu", "declined", cond_eq("email_answer", "no")),
            t("end_wrong_address", "address not theirs", cond_eq("email_answer", "wrong_address")),
        ],
    }
    nodes["send_pdf"] = api_node("send_pdf", "statement.pdf.send", {"customerNo": "{{customerNumber}}", "cardNumber": "{{card_number}}", "currencyType": "TL", "statementDate": "{{statement_date}}", "emailAddress": "{{email_addr}}"},
                                 "end_agent_service", [
                                     t("after_send", "sent", cond_eq("send_pdf_response.data.data.exitState", "DONE")),
                                 ], retries=0)
    nodes["after_send"] = {
        "name": "after_send", "node_type": "conversation", "on_enter": {"type": "tts", "text": "Ekstreniz kayıtlı e-posta adresinize gönderildi. Başka bir konuda yardımcı olabilir miyim?"},
        "task_message": AFTER_SEND_PROMPT, "max_node_turns": 5, "max_turn_transition": "end_menu",
        "extraction_schema": [{
            "name": "after_send_action", "type": "string", "enum_values": ["done", "resend", "week", "third_party", "stay"],
            "description": "Arayanın son mesajı: 'done' = teşekkür/veda/başka bir şey istemiyor/ana menü; 'resend' = ekstreyi tekrar göndermesini istiyor; 'week' = hesap kesim tarihini değiştirmek istiyor; 'third_party' = başkasının kartı için istek; 'stay' = diğer.",
            "min_confidence": 0.5}],
        "transitions": [
            t("end_menu", "done", cond_eq("after_send_action", "done")),
            t("send_pdf", "resend", cond_eq("after_send_action", "resend")),
            t("fetch_week", "week change", cond_eq("after_send_action", "week")),
            t("end_third_party", "third party", cond_eq("after_send_action", "third_party")),
        ],
    }
    nodes["email_none"] = {
        "name": "email_none", "node_type": "conversation", "on_enter": {"type": "tts", "text": "Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum. Dilerseniz hesap kesim tarihinizi değiştirebilirim."},
        "task_message": EMAIL_NONE_PROMPT, "max_node_turns": 5, "max_turn_transition": "end_menu",
        "extraction_schema": [{
            "name": "email_none_action", "type": "string", "enum_values": ["week", "done", "stay"],
            "description": "Arayanın son mesajı: 'week' = hesap kesim tarihini değiştirmek istiyor; 'done' = istemiyor/teşekkür/veda/hayır; 'stay' = diğer.",
            "min_confidence": 0.5}],
        "transitions": [
            t("fetch_week", "week change", cond_eq("email_none_action", "week")),
            t("end_menu", "done", cond_eq("email_none_action", "done")),
        ],
    }
    # statement week
    nodes["fetch_week"] = api_node("fetch_week", "statement.week.get", {"cardNumber": "{{card_number}}"}, "prep_week", [],
                                   mapping=[{"path": "data", "variable": "week_body"}])
    nodes["prep_week"] = code_node("prep_week", CODE_PREP_WEEK, "week_ask", [t("end_agent_week", "week service failed", cond_eq("week_state", "error"))])
    nodes["week_ask"] = {
        "name": "week_ask", "node_type": "conversation", "on_enter": {"type": "tts", "text": "{{week_intro}}"},
        "task_message": WEEK_PROMPT, "max_node_turns": 8, "max_turn_transition": "end_tries",
        "extraction_schema": [
            {"name": "week_choice", "type": "string", "enum_values": ["1", "2", "3", "4"], "description": "Arayanın seçtiği ayın haftası (1, 2, 3 veya 4). 'üçüncü hafta', '3. hafta', 'ayın üçüncü haftası' -> '3'. Hafta seçmediyse boş bırak; ayın günü veya tarih söylediyse de boş bırak.", "min_confidence": 0.5},
            {"name": "week_answer", "type": "string", "enum_values": ["no", "stay"], "description": "'no' = arayan değişiklik istemiyor/vazgeçti/hayır dedi; 'stay' = diğer.", "min_confidence": 0.5},
        ],
        "transitions": [
            t("check_week", "week chosen", cond_neq("week_choice", "")),
            t("end_menu", "declined", cond_eq("week_answer", "no")),
        ],
    }
    nodes["check_week"] = code_node("check_week", CODE_CHECK_WEEK, "week_ask", [t("fetch_decide", "valid week", cond_eq("week_check", "ok"))])
    nodes["fetch_decide"] = api_node("fetch_decide", "statement.week.decide", {"cardNumber": "{{card_number}}", "newStatementWeek": "{{chosen_week}}", "statementDay": "{{statement_day}}"}, "prep_confirm", [],
                                     mapping=[{"path": "data", "variable": "decide_body"}])
    nodes["prep_confirm"] = code_node("prep_confirm", CODE_PREP_CONFIRM, "week_confirm", [t("end_agent_week", "preview failed", cond_eq("decide_state", "error"))])
    nodes["week_confirm"] = {
        "name": "week_confirm", "node_type": "conversation", "on_enter": {"type": "tts", "text": "{{confirm_text}}"},
        "task_message": CONFIRM_PROMPT, "max_node_turns": 6, "max_turn_transition": "end_tries",
        "extraction_schema": [{
            "name": "confirm_answer", "type": "string", "enum_values": ["yes", "no", "stay"],
            "description": "Arayanın onay sorusuna cevabı: 'yes' = yalnızca açık ve net onay ('evet', 'onaylıyorum', 'evet onaylıyorum', 'evet, yapın'); 'no' = hayır/istemiyorum/vazgeçtim; 'stay' = belirsiz ('olur herhalde', 'sanırım', 'galiba', 'tamam gibi', 'herhalde'), tekrar isteği, soru ya da başka bir şey. Belirsiz cevabı ASLA 'yes' yapma.",
            "min_confidence": 0.5}],
        "transitions": [
            t("do_change", "clear yes", cond_eq("confirm_answer", "yes")),
            t("end_menu", "declined", cond_eq("confirm_answer", "no")),
        ],
    }
    nodes["do_change"] = api_node("do_change", "statement.week.change", {"cardNumber": "{{card_number}}", "newStatementWeek": "{{chosen_week}}", "statementDay": "{{statement_day}}"}, "end_agent_week", [
        t("after_change", "changed", cond_eq("do_change_response.data.data.exitState", "OK")),
    ], retries=0)
    nodes["after_change"] = {
        "name": "after_change", "node_type": "conversation", "on_enter": {"type": "tts", "text": "{{changed_text}} Başka bir konuda yardımcı olabilir miyim?"},
        "task_message": AFTER_CHANGE_PROMPT, "max_node_turns": 5, "max_turn_transition": "end_menu",
        "extraction_schema": [{
            "name": "after_change_action", "type": "string", "enum_values": ["done", "third_party", "email", "stay"],
            "description": "Arayanın son mesajı: 'done' = teşekkür/veda/başka bir şey istemiyor/ana menü; 'third_party' = eşinin/başkasının kartı için değişiklik ya da bilgi istiyor; 'email' = ekstresini e-posta ile istiyor; 'stay' = diğer (geri alma isteği, soru).",
            "min_confidence": 0.5}],
        "transitions": [
            t("end_menu", "done", cond_eq("after_change_action", "done")),
            t("end_third_party", "third party", cond_eq("after_change_action", "third_party")),
            t("email_confirm", "email", cond_and(("after_change_action", "equals", "email"), ("email_state", "equals", "yes"))),
            t("email_none", "email none", cond_and(("after_change_action", "equals", "email"), ("email_state", "equals", "no"))),
        ],
    }
    # ends
    nodes["end_menu"] = end_node("end_menu", "main_menu", "Sizi ana menüye yönlendiriyorum.")
    nodes["end_menu_aktar"] = end_node("end_menu_aktar", "main_menu_language", "Sizi ana menüye aktarıyorum.")
    nodes["end_no_card"] = end_node("end_no_card", "main_menu_no_card", "Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.")
    nodes["end_tries"] = end_node("end_tries", "main_menu_tries", "Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.")
    nodes["end_nodebt"] = end_node("end_nodebt", "main_menu_no_debt", "{{reading_text}}")
    nodes["end_wrong_address"] = end_node("end_wrong_address", "main_menu_wrong_address", "Anlıyorum, ekstreniz gönderilmeyecek. Kayıtlı e-posta adresinizi bu görüşmede değiştiremiyorum. Sizi ana menüye yönlendiriyorum.")
    nodes["end_third_party"] = end_node("end_third_party", "ivr_login_third_party", "Güvenlik nedeniyle yalnızca arayan kişinin kendi kartları için bilgi verebiliyor ve işlem yapabiliyorum. Sizi ana menüye yönlendiriyorum.")
    nodes["end_agent"] = end_node("end_agent", "agent_requested", "Sizi müşteri temsilcimize aktarıyorum.")
    nodes["end_agent_pay"] = end_node("end_agent_pay", "agent_payment", "Borç ödeme işleminiz için sizi müşteri temsilcimize aktarıyorum.")
    nodes["end_agent_dispute"] = end_node("end_agent_dispute", "agent_dispute", "Bu konuda size müşteri temsilcimiz yardımcı olacak, sizi aktarıyorum.")
    nodes["end_agent_service"] = end_node("end_agent_service", "agent_service_error", END_AGENT_SERVICE)
    nodes["end_agent_week"] = end_node("end_agent_week", "agent_week_error", "Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.")
    nodes["end_silence"] = end_node("end_silence", "silence_hangup", "Sesinizi alamadığım için görüşmeyi sonlandırıyorum.")

    end_keys = [k for k, v in nodes.items() if v["node_type"] == "end_call"]
    non_conv = [k for k, v in nodes.items() if v["node_type"] != "conversation"]
    def gnode(name, target, desc):
        return {"name": name, "description": desc, "condition": {"operator": "matches_intent", "description": desc},
                "node_type": "conversation", "on_enter": {"type": "silent"}, "passthrough": True, "passthrough_default_transition": target,
                "task_message": "Bu adımda hiçbir şey söyleme.", "excluded_nodes": end_keys + non_conv,
                "transitions": [t_always(target)]}
    globals_ = {
        "g_agent": gnode("g_agent", "end_agent", "Arayan açıkça bir müşteri temsilcisi, insan, yetkili ya da operatörle görüşmek istiyor (ödeme veya itiraz dışında)."),
        "g_pay": gnode("g_pay", "end_agent_pay", "Arayan borcunu ödemek istiyor ya da borcu nasıl/nereden ödeyebileceğini soruyor (ödeme kanalı, otomatik ödeme talimatı dahil). Sadece geçmişte ödeme yaptığını söylemek buna girmez."),
        "g_dispute": gnode("g_dispute", "end_agent_dispute", "Arayan borcun yanlış/hatalı olduğunu, tanımadığı bir harcama olduğunu ya da yaptığı bir ödemenin görünmediğini söylüyor ve itiraz ediyor."),
        "g_third": gnode("g_third", "end_third_party", "Arayan başka bir kişinin (eşi, annesi, babası, çocuğu, arkadaşı) kartı hakkında bilgi istiyor ya da o kart için işlem yapılmasını istiyor."),
        "g_foreign": gnode("g_foreign", "end_menu_aktar", "Arayan Türkçe dışında bir dilde (İngilizce, Almanca, Arapça vb.) konuşuyor; mesajı Türkçe değil."),
    }
    wf = {
        "initial_node": "fetch_cards",
        "system_prompt": SYSTEM,
        "nodes": nodes,
        "global_nodes": globals_,
        "test_variables": {"customerNumber": "95004361", "now": "2026-10-12T10:30:00+03:00"},
    }
    return wf

if __name__ == "__main__":
    wf = build()
    out = ROOT / "submission"; out.mkdir(exist_ok=True)
    (out / "final.workflow.local.json").write_text(json.dumps(wf, ensure_ascii=False, indent=1))
    if "--dry" in sys.argv:
        print(json.dumps(freya.validate_workflow("final-case dry", wf))[:2000]); sys.exit(0)
    res = freya.save_workflow("final-case", wf)
    print(json.dumps(res))
    freya.export_workflow(res["workflow_id"], str(out / "final.workflow.json"))
    print("exported", out / "final.workflow.json")

